'use client'; // Обов'язково для error.tsx

import { useEffect } from 'react';

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error(error);
  }, [error]);

  return (
    <div style={{ padding: '20px', border: '1px solid #e74c3c', backgroundColor: '#fadbd8', borderRadius: '6px', margin: '15px 0' }}>
      <h3 style={{ color: '#c0392b', marginTop: 0 }}>Сталася помилка в розділі спеціальностей!</h3>
      <p>{error.message || 'Не вдалося завантажити інформацію.'}</p>
      <button
        onClick={() => reset()}
        style={{ padding: '8px 16px', backgroundColor: '#e74c3c', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}
      >
        Спробувати знову (Reset)
      </button>
    </div>
  );
}